from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation

getcontext().prec = 80


def _store(value, int_digits, scale, signed=True, rounded=False):
    # Emula el almacenamiento en un campo PIC con escala fija:
    # ROUNDED -> ROUND_HALF_UP; sin ROUNDED -> truncamiento (ROUND_DOWN).
    # Desborde de dígitos enteros: truncamiento por la izquierda.
    q = Decimal(1).scaleb(-scale)
    v = Decimal(value).quantize(q, rounding=ROUND_HALF_UP if rounded else ROUND_DOWN)
    if not signed:
        v = abs(v)
    sign = -1 if v < 0 else 1
    a = abs(v)
    limit = Decimal(10) ** int_digits
    a = a % limit
    return (a * sign).quantize(q, rounding=ROUND_DOWN)


def _fmt(value, scale):
    q = Decimal(1).scaleb(-scale)
    v = Decimal(value).quantize(q, rounding=ROUND_DOWN)
    if v == 0:
        v = abs(v)
    return format(v, 'f')


def _parse(s, default="0"):
    try:
        t = str(s).strip() if s is not None else ""
        if t == "":
            t = default
        return Decimal(t)
    except (InvalidOperation, ValueError):
        return Decimal(default)


def run(inp: dict) -> dict:
    # LOAN-REQUEST
    principal = _store(_parse(inp.get("principal")), 9, 2, signed=True)      # S9(9)V99 COMP-3
    term = _store(_parse(inp.get("term_months")), 3, 0, signed=False)        # 9(3)
    score = _store(_parse(inp.get("credit_score")), 3, 0, signed=False)      # 9(3)
    age = _store(_parse(inp.get("customer_age")), 3, 0, signed=False)        # 9(3)

    # READ-REQUEST: inicialización de LOAN-RESULT
    status = ""
    error_code = ""
    annual_rate = Decimal("0.0000")
    monthly_payment = Decimal("0.00")
    insurance = Decimal("0.00")
    total_interest = Decimal("0.00")
    total_paid = Decimal("0.00")

    def _out():
        return {
            "status": status,
            "error_code": error_code,
            "annual_rate": _fmt(annual_rate, 4),
            "monthly_payment": _fmt(monthly_payment, 2),
            "insurance": _fmt(insurance, 2),
            "total_interest": _fmt(total_interest, 2),
            "total_paid": _fmt(total_paid, 2),
        }

    # VALIDATE-INPUT
    if principal < Decimal("1000.00") or principal > Decimal("500000.00"):
        status = "REJECTED"
        error_code = "E01"
    else:
        if term < 6 or term > 360:
            status = "REJECTED"
            error_code = "E02"
        else:
            # DIVIDE ... GIVING WS-TERM-YEARS PIC 9(3): truncamiento
            ws_term_years = _store(term / Decimal(12), 3, 0, signed=False)
            # COMPUTE WS-MATURITY-AGE PIC 9(3) sin ROUNDED
            ws_maturity_age = _store(age + ws_term_years, 3, 0, signed=False)
            if ws_maturity_age > 75:
                status = "REJECTED"
                error_code = "E03"
    if status == "REJECTED":
        return _out()

    # DETERMINE-RATE
    if score >= 750:
        annual_rate = _store(Decimal("0.0899"), 1, 4, signed=False)
    elif score >= 650:
        annual_rate = _store(Decimal("0.1299"), 1, 4, signed=False)
    elif score >= 550:
        annual_rate = _store(Decimal("0.1899"), 1, 4, signed=False)
    else:
        status = "REJECTED"
        error_code = "E04"
    if status != "REJECTED":
        if score >= 800 and term <= 60:
            annual_rate = _store(annual_rate - Decimal("0.0025"), 1, 4, signed=False)
        if term > 120:
            annual_rate = _store(annual_rate + Decimal("0.0050"), 1, 4, signed=False)
    if status == "REJECTED":
        return _out()

    # CALC-PAYMENT
    ws_rate_monthly = _store(annual_rate / Decimal(12), 1, 9, signed=False, rounded=True)   # 9V9(9)
    n = int(term)
    ws_factor = _store((Decimal(1) + ws_rate_monthly) ** n, 7, 9, signed=False, rounded=True)  # 9(7)V9(9)
    monthly_payment = _store(principal * ws_rate_monthly * ws_factor / (ws_factor - Decimal(1)),
                             9, 2, signed=True, rounded=True)

    # CALC-INSURANCE
    if age < 40:
        ws_ins_rate = _store(Decimal("0.00035"), 1, 5, signed=False)
    elif age < 60:
        ws_ins_rate = _store(Decimal("0.00055"), 1, 5, signed=False)
    else:
        ws_ins_rate = _store(Decimal("0.00095"), 1, 5, signed=False)
    insurance = _store(principal * ws_ins_rate, 7, 2, signed=True, rounded=True)

    # CALC-TOTALS (sin ROUNDED -> truncamiento)
    total_interest = _store(monthly_payment * term - principal, 9, 2, signed=True)
    total_paid = _store((monthly_payment + insurance) * term, 9, 2, signed=True)

    status = "APPROVED"
    return _out()
